package io.github.rawwise.benchmark.vbench.executors;

import java.nio.charset.StandardCharsets;
import java.util.HashMap;
import java.util.Map;
import lombok.extern.slf4j.Slf4j;

/**
 * CogVideoX video generation model stub client.
 *
 * <p>Real production deployment calls CogVideoX HTTP API(OpenAPI or local inference service). This
 * stub provides deterministic output, for: - E2E testing and integration testing - VBench offline
 * flow (video actually generated by Python side, Java side only does scheduling)
 *
 * <p>Call interface: request: { prompt, reference_embedding, drift_description, frame_range }
 * response: { videoBytes, generationLatencyMs, modelVersion }
 */
@Slf4j
public class CogVideoXClient {

    private static final String MODEL_VERSION = "cogvideox-5b-stub";

    /**
     * Generate video or regenerate specified frame range.
     *
     * @param request generation request (with prompt and optional reference conditions)
     * @return generation response (with video byte stream and metadata)
     */
    public GenerationResponse generate(GenerationRequest request) {
        if (request == null || request.prompt() == null) {
            throw new IllegalArgumentException("prompt is required");
        }

        long start = System.currentTimeMillis();
        log.info(
                "CogVideoX stub generating: prompt='{}', hasReference={}, frameRange={}",
                truncate(request.prompt(), 50),
                request.referenceEmbedding() != null,
                request.frameRange());

        // Stub: Use prompt hash to generate deterministic video bytes
        byte[] videoBytes =
                ("STUB_VIDEO:" + request.prompt() + ":" + request.frameRange())
                        .getBytes(StandardCharsets.UTF_8);

        long latencyMs = System.currentTimeMillis() - start;
        Map<String, Object> metadata = new HashMap<>();
        metadata.put("prompt_length", request.prompt().length());
        metadata.put("has_reference", request.referenceEmbedding() != null);
        metadata.put("frame_range", request.frameRange());

        return new GenerationResponse(videoBytes, latencyMs, MODEL_VERSION, metadata);
    }

    private String truncate(String s, int max) {
        return s.length() <= max ? s : s.substring(0, max) + "...";
    }

    public record GenerationRequest(
            String prompt,
            float[] referenceEmbedding,
            String driftDescription,
            String frameRange,
            Map<String, Object> extraParams) {
        public GenerationRequest {
            extraParams = extraParams == null ? Map.of() : Map.copyOf(extraParams);
        }

        public static GenerationRequest of(String prompt) {
            return new GenerationRequest(prompt, null, null, "0-end", Map.of());
        }
    }

    public record GenerationResponse(
            byte[] videoBytes,
            long generationLatencyMs,
            String modelVersion,
            Map<String, Object> metadata) {}
}
